# keratinisation, classify ichthyoses, X-linked ichthyosis, Netherton, Refsum's, Rud's, palmoplantar keratodermas,
# acquired keratodermas, Howel–Evans, porokeratosis types, transepidermal elimination); facts checked with IADVL 5e
# and the 2009 Sorèze ichthyosis consensus.
PYQ = "Previous-year PG question papers (Sahana P Raju, Solved Papers Dermatology)"
IA = "IADVL Textbook of Dermatology 5e"

D = [
dict(case="Porokeratosis", src=f"{PYQ}; {IA} (Porokeratosis)",
 qa=[
 ("What is porokeratosis?", ["Group of clonal disorders of keratinisation characterised clinically by annular plaques with a thread-like raised keratotic rim and histologically by the cornoid lamella; defects in the mevalonate pathway (MVK, PMVK, MVD, FDPS genes) with second-hit somatic mutation in lesions"]),
 ("Describe the types and clinical features (PYQ).", ["Porokeratosis of Mibelli (classic): one or few plaques with a raised furrowed keratotic ridge and atrophic centre, childhood, limbs", "Disseminated superficial actinic porokeratosis (DSAP): commonest; multiple small (5–10 mm) annular brownish lesions on sun-exposed extensor limbs, adults; worsens in summer/immunosuppression", "Disseminated superficial porokeratosis (non-actinic — also sun-protected sites; immunosuppressed)", "Linear porokeratosis (along Blaschko's lines — highest malignancy risk)", "Porokeratosis palmaris et plantaris disseminata (palms/soles then generalised)", "Punctate porokeratosis (palms/soles), genitogluteal/ptychotropic, hypertrophic verrucous, eruptive (paraneoplastic/inflammatory), porokeratotic eccrine ostial and dermal duct naevus (PEODDN)"]),
 ("What is a cornoid lamella?", ["Thin column of tightly packed parakeratotic cells angled away from the centre, arising from an invagination of epidermis with absent/reduced granular layer and dyskeratotic cells at its base — corresponds to the raised rim", "Also seen focally in actinic keratosis, verrucae, seborrhoeic keratosis (not diagnostic alone)"]),
 ("Malignant potential.", ["SCC (also BCC, Bowen's) develops in ~7–11% — highest in linear and large long-standing lesions (Mibelli), lowest in DSAP; immunosuppression increases risk"]),
 ("Enumerate disorders of transepidermal elimination (PYQ).", ["Primary perforating disorders: Kyrle's disease, perforating folliculitis, reactive perforating collagenosis, elastosis perforans serpiginosa (Down syndrome, penicillamine, Ehlers–Danlos, Marfan), acquired perforating dermatosis (diabetes + chronic renal failure)", "Secondary: granuloma annulare (perforating), necrobiosis lipoidica, pseudoxanthoma elasticum, calcinosis cutis, chondrodermatitis, gout, foreign bodies, chromoblastomycosis, porokeratosis"]),
 ("Differential diagnosis.", ["DSAP vs actinic keratosis, lichen planus (annular/atrophic), tinea corporis, granuloma annulare, seborrhoeic keratosis, Bowen's, elastosis perforans serpiginosa; linear porokeratosis vs linear epidermal naevus/linear LP"]),
 ("Treatment.", ["Photoprotection, regular skin surveillance (biopsy any nodules/ulcers)", "Topical: 5-FU, imiquimod, vitamin D analogues, retinoids, diclofenac, lovastatin 2% + cholesterol 2% (topical statin–cholesterol — targets mevalonate pathway; newer effective option)", "Physical: cryotherapy, CO2/Er:YAG/fractional lasers, PDT, curettage, excision of small lesions", "Oral acitretin for extensive disease/chemoprevention"]),
 ],
 spot=["Annular plaque with thread-like keratotic ridge — porokeratosis; cornoid lamella", "Linear porokeratosis — highest SCC risk", "Topical lovastatin–cholesterol"]),

dict(case="Callus (callosity)", src=f"{PYQ}; {IA} (Mechanical and physical injuries; keratoderma)",
 qa=[
 ("What is a callus?", ["Diffuse, plaque-like, yellowish thickening of the stratum corneum (hyperkeratosis) at sites of repeated friction or intermittent pressure, without a central core; protective response", "Occupational calluses ('occupational stigmata'): tailor's (fingers), guitarist's fingertips, prayer callus (forehead/knees — 'prayer nodules'), tennis player's palm, writer's callus, cobbler's, farmer's palms; Russell's sign (knuckle calluses from self-induced vomiting in bulimia)"]),
 ("Pathogenesis.", ["Repeated friction/pressure → increased keratinocyte proliferation and retention hyperkeratosis to protect underlying tissue", "Predisposing: ill-fitting footwear, high heels, foot deformities (hallux valgus, flat/high-arched feet), abnormal gait, obesity, peripheral neuropathy (diabetes, leprosy — calluses precede neuropathic ulcers), barefoot walking"]),
 ("Differentiate callus, corn and plantar wart.", ["Callus: broad diffuse thickening over pressure/friction areas, skin lines preserved, little pain, no core", "Corn: circumscribed with central translucent conical core pointing inwards, painful on direct pressure, skin lines pass through", "Wart: interrupts skin lines, black dots (thrombosed capillaries) on paring, painful on lateral squeeze"]),
 ("Why are calluses important in diabetes and leprosy?", ["In insensate feet, callus acts like a foreign body increasing plantar pressure → haemorrhage beneath callus → neuropathic ulcer; regular callus debridement and offloading footwear (MCR) prevent ulceration"]),
 ("Management.", ["Remove cause: proper well-fitting footwear, padding, insoles/orthotics, correct foot deformity, offloading", "Paring with a scalpel or pumice stone after soaking", "Keratolytics: salicylic acid 10–40% (plasters/ointments), urea 20–40%, lactic acid; emollients", "Avoid aggressive self-treatment in diabetics; podiatry referral"]),
 ],
 spot=["Diffuse yellow plaque over pressure point without core — callus", "Calluses in insensate foot precede neuropathic ulcers"]),

dict(case="Corn (clavus)", src=f"{PYQ}; {IA} (Mechanical injuries)",
 qa=[
 ("What is a corn?", ["Sharply circumscribed, painful hyperkeratotic lesion with a central translucent, conical keratin core (radix) that presses on underlying dermal nerves; due to localised repeated pressure over bony prominences"]),
 ("Types.", ["Hard corn (heloma durum): dorsolateral fifth toe, tops of interphalangeal joints (claw/hammer toes), sole over metatarsal heads", "Soft corn (heloma molle): macerated white lesion in the interdigital space (commonly 4th web) from opposing bony prominences — may be mistaken for tinea pedis", "Seed corns (heloma miliare): multiple tiny corns on weight-bearing sole", "Vascular and neurofibrous corns (painful, bleeding on paring)"]),
 ("Differential diagnosis.", ["Plantar wart (black dots, interrupted skin lines, pain on lateral pressure), callus, punctate keratoderma, porokeratosis plantaris discreta, foreign body, eccrine poroma, tinea pedis/soft corn"]),
 ("Paring test.", ["Paring a corn reveals a central translucent core with intact skin lines; paring a wart shows pinpoint bleeding black dots and interrupted dermatoglyphics"]),
 ("Management.", ["Relieve pressure: wide-toed shoes, corn pads/doughnut cushions, toe separators (soft corn), orthotics, correct toe deformities (surgery for persistent cases — exostectomy, arthroplasty)", "Paring/enucleation of the core with a scalpel — immediate relief", "Keratolytic plasters (salicylic acid 40%), urea creams; avoid caustic corn caps in diabetics/peripheral vascular disease", "Recurrence common unless mechanical cause corrected"]),
 ],
 spot=["Painful circumscribed lesion with central translucent core over bony prominence — corn", "Soft corn in 4th toe web"]),

dict(case="Ichthyosis", src=f"{PYQ}; {IA} (Ichthyoses); 2009 Sorèze consensus classification",
 qa=[
 ("Describe the process of keratinisation (PYQ).", ["Basal keratinocytes divide → spinous cells (keratins K1/K10 replace K5/K14, desmosomes) → granular layer (keratohyaline granules with profilaggrin, loricrin; lamellar bodies with lipids and enzymes) → stratum corneum: cornified cell envelope (crosslinked by transglutaminase-1) with lipid envelope, extracellular lipid lamellae (ceramides, cholesterol, free fatty acids — 'bricks and mortar'), desquamation by proteases (kallikreins KLK5/7, inhibited by LEKTI) cleaving corneodesmosomes", "Ichthyoses result from defects at any of these steps — increased production (proliferation hyperkeratosis) or decreased shedding (retention hyperkeratosis)"]),
 ("Classify ichthyoses (PYQ).", ["Non-syndromic inherited: common — ichthyosis vulgaris (FLG, AD-semidominant), recessive X-linked ichthyosis (STS); autosomal recessive congenital ichthyosis (ARCI) — harlequin ichthyosis (ABCA12), lamellar ichthyosis (TGM1), congenital ichthyosiform erythroderma (ALOX12B, ALOXE3, NIPAL4); keratinopathic — epidermolytic ichthyosis (K1/K10), superficial epidermolytic ichthyosis (K2), ichthyosis with confetti; others — loricrin keratoderma, erythrokeratodermia variabilis, peeling skin syndrome", "Syndromic: Netherton (SPINK5), Sjögren–Larsson (ALDH3A2 — spasticity, intellectual disability, glistening retinal dots), Refsum (phytanic acid), Conradi–Hünermann–Happle (CDPX2 — Blaschkoid, chondrodysplasia punctata), KID syndrome (keratitis–ichthyosis–deafness, GJB2), CHILD (NSDHL — unilateral), trichothiodystrophy (IBIDS), neutral lipid storage disease (Chanarin–Dorfman — lipid vacuoles in leucocytes), Rud syndrome, multiple sulphatase deficiency, ARC, MEDNIK", "Acquired ichthyosis: lymphoma (Hodgkin's), leprosy (LL), HIV, sarcoidosis, malnutrition, hypothyroidism, CKD, drugs (clofazimine, statins, nicotinic acid, kava)"]),
 ("Ichthyosis vulgaris — features.", ["Commonest (1:250); onset after 2–3 months of age; fine white/grey scales on extensors (especially shins), flexures spared; palmar hyperlinearity, keratosis pilaris; strongly associated with atopic dermatitis; improves in summer and with age", "Histology: reduced/absent granular layer, compact orthokeratosis"]),
 ("Discuss X-linked ichthyosis (PYQ).", ["Recessive X-linked steroid sulphatase (STS) deficiency (deletion Xp22.3) — males; cholesterol sulphate accumulates and impairs desquamation", "Onset at birth/first weeks; large dark-brown polygonal adherent scales on trunk, extensors and flexures, sides of neck ('dirty neck'); palms, soles and face (central) spared; does not improve much with age", "Associations: comma-shaped corneal opacities (asymptomatic, also in carrier mothers), cryptorchidism (testicular cancer risk), ADHD/autism; contiguous gene deletion — Kallmann syndrome (anosmia), chondrodysplasia punctata", "Obstetric: low maternal oestriol (placental sulphatase deficiency) → failure of labour onset/prolonged labour", "Diagnosis: increased serum cholesterol sulphate, rapid lipoprotein electrophoresis (fast-moving LDL), STS enzyme assay, FISH for deletion"]),
 ("Describe lamellar ichthyosis and collodion baby.", ["Collodion baby: newborn encased in a shiny, tight, cellophane-like membrane with ectropion, eclabium, flattened ears; sheds in 2–4 weeks; underlying ARCI (lamellar/CIE) most commonly, or self-healing collodion baby (~10%)", "Risks: hypothermia, dehydration/hypernatraemia, infection, poor feeding — nurse in humidified incubator, emollients (white soft paraffin), avoid keratolytics, monitor electrolytes", "Lamellar ichthyosis (TGM1): large plate-like dark scales over whole body including flexures, ectropion, eclabium, scarring alopecia, palmoplantar keratoderma, heat intolerance (hypohidrosis)"]),
 ("What is harlequin ichthyosis?", ["Most severe ARCI (ABCA12 — defective lipid transport into lamellar bodies): thick armour-like plates separated by deep red fissures, severe ectropion, eclabium, rudimentary ears, restricted limb movement; high neonatal mortality — systemic retinoids (acitretin) improve survival"]),
 ("Write a short note on Comèl–Netherton syndrome (PYQ).", ["Autosomal recessive SPINK5 mutation (LEKTI deficiency) → uncontrolled kallikrein activity → excess desquamation and Th2 inflammation", "Triad: congenital ichthyosiform erythroderma or ichthyosis linearis circumflexa (migratory polycyclic plaques with double-edged scale), trichorrhexis invaginata ('bamboo hair' — eyebrows best), atopic diathesis (high IgE, food allergy, asthma)", "Complications: hypernatraemic dehydration, failure to thrive, sepsis, high systemic absorption of topical drugs (tacrolimus); treatment — emollients, topical tacrolimus cautiously, IVIG, dupilumab/secukinumab (reports)"]),
 ("Write short notes on Refsum's disease (PYQ).", ["Autosomal recessive phytanoyl-CoA hydroxylase (PHYH) or PEX7 deficiency → phytanic acid accumulation (dietary — dairy, ruminant fat, fish)", "Ichthyosis-like scaling (adult onset, mild), retinitis pigmentosa (night blindness — earliest), peripheral neuropathy, cerebellar ataxia, deafness, anosmia, cardiac arrhythmias, short metatarsals", "Lipid vacuoles in basal keratinocytes on histology; high plasma phytanic acid; treatment — phytanic-acid restricted diet, plasmapheresis"]),
 ("Describe Rud's syndrome (PYQ).", ["Rare: congenital ichthyosis + hypogonadism + short stature + intellectual disability + epilepsy (± retinitis pigmentosa); some cases overlap with contiguous gene deletion of X-linked ichthyosis/Kallmann"]),
 ("Describe epidermolytic ichthyosis.", ["Autosomal dominant K1/K10 mutation (bullous congenital ichthyosiform erythroderma): blistering and erythema at birth, later corrugated, ridged, malodorous warty hyperkeratosis especially in flexures; histology — epidermolytic hyperkeratosis (vacuolisation of granular/spinous cells with clumped keratohyaline)", "Mosaic form = epidermolytic epidermal naevus; gonadal mosaicism → offspring with generalised disease (genetic counselling)"]),
 ("Management of ichthyoses.", ["Emollients and humectants (petrolatum, glycerol, urea 5–10%), keratolytics (lactic acid, salicylic acid — caution for salicylism in children/ large areas, propylene glycol), bath oils, soaking and gentle scrubbing", "Topical retinoids (tazarotene) for localised thick scale; calcipotriol (limited areas)", "Systemic retinoids: acitretin 0.3–1 mg/kg/day or isotretinoin for severe ARCI, epidermolytic ichthyosis, harlequin (lifelong monitoring — bone, lipids, LFT, teratogenicity)", "Eye care for ectropion, ear cleaning, heat precautions, vitamin D supplementation, nutrition, physiotherapy; genetic counselling and prenatal diagnosis", "Emerging: IL-17/IL-23 biologics and dupilumab in some ichthyoses (Netherton, CIE)"]),
 ],
 spot=["Fine shin scales + palmar hyperlinearity + atopy — ichthyosis vulgaris (FLG)", "Dark 'dirty neck' scales in a boy + corneal opacities + cryptorchidism — X-linked ichthyosis (STS)", "Collodion baby — humidified incubator, emollients"]),

dict(case="Keratosis pilaris", src=f"{PYQ}; {IA} (Follicular keratoses)",
 qa=[
 ("What is keratosis pilaris (KP)?", ["Very common, benign, inherited (autosomal dominant with variable penetrance) follicular keratinisation disorder: rough, skin-coloured to red, keratotic follicular papules ('chicken skin') on extensor upper arms, thighs, buttocks, cheeks (children)", "Begins in childhood, peaks in adolescence, improves with age; worse in winter/dry climate"]),
 ("Associations.", ["Atopic dermatitis and ichthyosis vulgaris (FLG mutations), obesity, diabetes, hypothyroidism, Down syndrome, Noonan/cardiofaciocutaneous syndromes, drugs (BRAF inhibitors — vemurafenib, lithium)"]),
 ("Variants.", ["KP rubra (prominent erythema), KP alba", "Keratosis pilaris atrophicans group: ulerythema ophryogenes (lateral eyebrows — atrophy and loss; Noonan, Cornelia de Lange), atrophoderma vermiculatum (honeycomb atrophy on cheeks), keratosis follicularis spinulosa decalvans (X-linked, scarring alopecia of scalp, photophobia)", "Erythromelanosis follicularis faciei et colli (red-brown pigmentation with follicular papules on cheeks/neck)", "Keratosis pilaris rubra faceii"]),
 ("Histopathology.", ["Keratin plug distending the follicular infundibulum, often with a coiled/twisted hair, mild perifollicular lymphocytic infiltrate"]),
 ("Differential diagnosis.", ["Phrynoderma (nutritional; elbows/knees, larger spiny papules), lichen spinulosus (grouped spiny papules), Darier's disease (greasy seborrhoeic distribution), PRP (follicular knuckle papules), folliculitis (pustules), lichen nitidus, scurvy (perifollicular haemorrhages, corkscrew hairs), follicular eczema, acne (comedones)"]),
 ("Treatment.", ["Reassurance — benign, improves with age", "Emollients and keratolytics: urea 10–20%, lactic acid 12%, salicylic acid 3–6%, glycolic acid; gentle exfoliation", "Topical retinoids (tretinoin, adapalene, tazarotene); short course of mild topical steroids for red/itchy KP", "Lasers: PDL/KTP for erythema, long-pulsed Nd:YAG/diode laser hair removal, Q-switched Nd:YAG for pigmentation; microdermabrasion"]),
 ],
 spot=["Rough follicular papules on outer arms of an atopic adolescent — keratosis pilaris", "Ulerythema ophryogenes — lateral eyebrow loss"]),

dict(case="Lichen spinulosus", src=f"{PYQ}; {IA} (Follicular keratoses)",
 qa=[
 ("What is lichen spinulosus?", ["Uncommon follicular keratotic eruption, mainly in children and adolescents (boys), with grouped skin-coloured follicular papules each bearing a filiform keratin spine, arranged in round/oval plaques 2–6 cm on neck, buttocks, abdomen, extensor limbs, trunk; feels like a nutmeg grater"]),
 ("Aetiology / associations.", ["Mostly idiopathic; atopy, vitamin A deficiency (overlap with phrynoderma), seborrhoeic dermatitis; reported in HIV (with PRP type VI), Crohn's disease, alcoholism, drugs (gold, thallium), lymphoma, syphilis, fungal (id)"]),
 ("Histopathology.", ["Dilated follicular infundibula filled with keratin plugs (spinous projections above the surface), sparse perifollicular lymphocytes"]),
 ("Differential diagnosis.", ["Keratosis pilaris (diffuse, not grouped plaques), phrynoderma (malnutrition, larger papules on elbows/knees), PRP (follicular papules on knuckles, orange keratoderma), lichen nitidus (shiny, flat, not spiny), lichen scrofulosorum (TB — yellow-brown lichenoid grouped papules; Mantoux positive), trichodysplasia spinulosa (polyomavirus in immunosuppressed — face), multiple minute digitate hyperkeratoses, follicular eczema, Darier's disease"]),
 ("Treatment.", ["Often asymptomatic and self-limiting (months to years)", "Keratolytics: urea 10–20%, salicylic acid 3–6%, lactic acid 12%; topical retinoids; mild topical steroids", "Correct nutritional deficiencies (vitamin A); treat underlying cause (HIV etc.)"]),
 ],
 spot=["Grouped spiny follicular papules forming a plaque on the neck of a child — lichen spinulosus", "Differentiate from lichen scrofulosorum (TB)"]),

dict(case="Palmoplantar keratoderma", src=f"{PYQ}; {IA} (Palmoplantar keratodermas)",
 qa=[
 ("Define palmoplantar keratoderma (PPK).", ["Persistent abnormal thickening (hyperkeratosis) of the palms and soles, inherited or acquired"]),
 ("Discuss classification of palmoplantar keratodermas (PYQ).", ["Inherited — by pattern: diffuse (whole palm/sole — Unna–Thost/Vörner (epidermolytic, KRT9/KRT1), mal de Meleda (SLURP1 — transgrediens, glove-and-stocking, malodour, AR), Bothnian (aquaporin 5, aquagenic whitening), Greither's), focal/striate (pressure areas, linear — desmoglein 1, desmoplakin, keratin 1/16; pachyonychia congenita — KRT6/16/17; Howel–Evans), punctate (multiple small keratotic papules/pits — AAGAB; Buschke–Fischer–Brauer)", "With associated features (syndromic): Papillon–Lefèvre (CTSC — periodontitis with early tooth loss, psoriasiform plaques, pyogenic infections), Vohwinkel (GJB2 mutilating — pseudoainhum, honeycomb keratoderma, starfish knuckle keratoses, deafness; loricrin variant with ichthyosis), Naxos (plakoglobin — woolly hair, arrhythmogenic right ventricular cardiomyopathy), Carvajal (desmoplakin — woolly hair, left ventricular cardiomyopathy), Clouston (hidrotic ectodermal dysplasia), Richner–Hanhart (tyrosinaemia type II — painful focal PPK, corneal ulcers, intellectual disability), Huriez (scleroatrophic — SCC risk), Olmsted (periorificial plaques, mutilating), Howel–Evans", "Acquired: keratoderma climactericum (menopausal women — heels), psoriasis, eczema, lichen planus, PRP, tinea pedis/manuum, reactive arthritis (keratoderma blennorrhagicum), arsenical keratoses, crusted scabies, secondary syphilis, myxoedema, drugs (capecitabine, venlafaxine, lithium, BRAF inhibitors), CTCL/Sézary, paraneoplastic (tripe palms, acrokeratosis paraneoplastica of Bazex — SCC of upper aerodigestive tract), lymphoedema, aquagenic keratoderma, chronic arsenicosis"]),
 ("Write a short note on Howel–Evans syndrome (PYQ).", ["Autosomal dominant tylosis with oesophageal cancer (TOC) — RHBDF2 mutation; focal PPK (pressure areas of soles) beginning in late childhood, oral leukoplakia, follicular papules, and very high lifetime risk (~95% by 65 y) of oesophageal squamous cell carcinoma — needs annual upper GI endoscopy"]),
 ("What is 'transgrediens'?", ["Extension of keratoderma beyond the palms/soles to the dorsal surfaces (e.g. mal de Meleda, Greither's, Olmsted) — vs 'non-transgrediens' confined to palmoplantar skin (Unna–Thost)"]),
 ("Investigations.", ["Family history, pattern, associated features (hair, teeth, nails, hearing, heart), KOH (tinea), biopsy (epidermolytic vs non-epidermolytic), genetic testing; ECG/echo in woolly-hair syndromes; endoscopy (Howel–Evans); screen for malignancy in acquired adult onset"]),
 ("Treatment.", ["Mechanical paring, soaks, keratolytics (salicylic acid 5–20%, urea 10–40%, lactic acid), topical retinoids, calcipotriol", "Systemic retinoids (acitretin 10–25 mg/day) — effective but painful sensitivity if over-treated (epidermolytic types), lowest effective dose", "Treat hyperhidrosis and secondary fungal/bacterial infections, proper footwear and orthotics; surgical release of constricting bands (pseudoainhum)", "Treat cause in acquired PPK (psoriasis, hypothyroidism, drug withdrawal, tumour)"]),
 ],
 spot=["Focal PPK + family history of oesophageal cancer — Howel–Evans (tylosis)", "PPK + early loss of teeth — Papillon–Lefèvre", "PPK + woolly hair + cardiomyopathy — Naxos/Carvajal"]),
]
